"""L2-0D_ranks.py -- settles the e-descent OPEN cases (b<a<30) by rank 0 of E_rho / E_tau / J1 / J2,
proving rank 0 with ellrank on the whole Q-isogeny class (rank is an isogeny invariant).
Python 3 + cypari2, PARI/GP 2.17.2.  Needs L2_0B_verify.py (same Drive folder) in the working directory:
the e-descent functions (decide etc.) are taken from it.   Run: python3 L2-0D_ranks.py   (about 9 minutes)
Exclusion rules used after rank 0 is proved:
  E_rho: torsion of order 4 (E(Q)=E[2](Q), the R-5 argument)
  E_tau: torsion exactly Z/2 x Z/4 (the R-17 argument)
  J1/J2: Sel_e = {1} and torsion of order 8 (R-22, Prop. 1)
"""
exec(open('L2_0B_verify.py').read().split("# ===================== reproduction of the bundle")[0])
GP = r"""
ehomo(e1,e2,e3) = ellinit([0,-(e1+e2+e3),0,e1*e2+e1*e3+e2*e3,-e1*e2*e3]);
Erho(a,b) = my(k=4*a*b*(a^2-b^2)); ehomo(k,-k,-(a^2+b^2)^2);
Etau(a,b) = my(n=a^2-b^2,m=a*b); ehomo(8*n^2*m^2,-8*n^2*m^2,-(n^4+16*m^4));
oddp(x) = my(y=abs(x)); y/2^valuation(y,2);
om(x) = omega(oddp(x));
n1mod8(x) = my(f=factor(oddp(x))[,1]); sum(i=1,#f, f[i]%8==1);
c1(x) = my(f=factor(oddp(x))[,1]); sum(i=1,#f, f[i]%4==1);
c3(x) = my(f=factor(oddp(x))[,1]); sum(i=1,#f, f[i]%4==3);
eps(a,b) = my(m=a*b); if(m%4==2, 1, if(m%2==1 && (m%8==3 || m%8==5), 1, -1));
eps1(a,b) = if((a*b)%4==2, 1, -1);
eps2(a,b) = my(m=a*b); if(m%2==1 && (m%8==3 || m%8==5), 1, -1);
thm(a,b) = my(P=a^2+2*a*b-b^2, Q=a^2-2*a*b-b^2, N1=om(a*b*(a^2-b^2))+n1mod8(P*Q)); [-eps(a,b)*(-1)^N1, (-1)^(N1+om(a^2+b^2))];
J1(a,b) = my(u=2*a*b, v=a^2-b^2); ellinit([0, v^2-u^2, 0, -u^2*v^2, 0]);
J2(a,b) = my(u=2*a*b, v=a^2-b^2); ellinit([0, u^2-v^2, 0, -u^2*v^2, 0]);
JF1(a,b) = ellinit(ellfromeqn(y^2-(b^2*x^2+a^2)*(a^2*x^2+b^2)));
JF2(a,b) = ellinit(ellfromeqn(y^2-((a-b)^2*x^2+(a+b)^2)*((a+b)^2*x^2+(a-b)^2)));
wJ1(a,b) = -eps1(a,b)*(-1)^(om(a*b) + om(a^2+b^2) + c1(a^2-b^2));
wJ2(a,b) = -eps2(a,b)*(-1)^(om(a^2-b^2) + om(a^2+b^2) + c1(a*b));
"""

for line in GP.strip().split("\n"): pari(line)
from math import gcd
from collections import Counter
mk={'rho':'Erho','tau':'Etau','J1':'J1','J2':'J2'}
def rank0_class(E):
    """True if some curve in the Q-isogeny class of E has ellrank upper bound 0 (effort 1 or 3);
       'pos' if a lower bound >= 1 is proved; None otherwise"""
    for C in pari.ellisomat(E)[0]:
        Ci = pari.ellinit(C[0])
        for eff in (1, 3):
            r = pari.ellrank(Ci, eff); lo, hi = int(r[0]), int(r[1])
            if hi == 0: return True
            if lo > 0: return 'pos'
    return None
def tors_ok(name, E, sel):
    t = pari.elltors(E); n = int(t[0]); cyc = [int(x) for x in t[1]]
    return (name == 'rho' and n == 4) or (name == 'tau' and cyc == [4, 2]) or (name in ('J1','J2') and n == 8 and sel == [1])
stats = Counter(); remaining = []
for a in range(2, 30):
    for b in range(1, a):
        if gcd(a, b) != 1: continue
        r = decide(a, b)
        if r['verdict'].startswith('EXCL'): stats['e-descent'] += 1; continue
        sel = r['sel']
        wr, wt = [int(x) for x in pari(f'thm({a},{b})')]; w1, w2 = int(pari(f'wJ1({a},{b})')), int(pari(f'wJ2({a},{b})'))
        cands = [n for n, w in (('rho', wr), ('tau', wt), ('J2', w2), ('J1', w1)) if w == 1 and (n in ('rho','tau') or sel == [1])]
        done = None
        for n in cands:
            E = pari(f'{mk[n]}({a},{b})')
            if rank0_class(E) is True and tors_ok(n, E, sel): done = n; break
        if done: stats['rank0 ('+done+')'] += 1
        else: remaining.append((a, b, (wr, wt, w1, w2), sel))
print("excluded:", dict(stats), " total", sum(stats.values()), " remaining:", len(remaining))
hc = [x for x in remaining if x[2] == (-1, -1, -1, -1)]
print("remaining in hard core (all four -1):", len(hc), [f"{a}/{b}" for a, b, _, _ in hc])
print("other remaining:", [f"{a}/{b}" for a, b, w, _ in remaining if w != (-1, -1, -1, -1)])

# Expected output (PARI/GP 2.17.2, about 9 minutes):
# excluded: {'e-descent': 183, 'rank0 (tau)': 23, 'rank0 (rho)': 36, 'rank0 (J2)': 1}  total 243  remaining: 26
# remaining in hard core (all four -1): 6 ['17/16', '22/13', '23/22', '25/14', '26/25', '27/22']
# other remaining: ['11/8', '14/13', '15/8', '19/3', '22/1', '23/7', '23/21', '24/1', '24/17', '25/4', '25/23', '26/23', '27/1', '27/2', '28/5', '28/27', '29/18', '29/21', '29/24', '29/25']
